using System.Collections.Generic;
using System.Data;
using BOSCommon;
using BOSComponent;
using System.Windows.Forms;
using System.Linq;

namespace BOSERP.Modules.HRDepartment
{
    #region HRDepartmentModule
    //-----------------------------------------------------------
