    public class HRDepartmentModule : BaseModuleERP
    {
        #region Constant
        public const string RoomBedGridControlName = "fld_dgcHRRoomBeds";
        private HREmployeesController _employeeCtrl;
        private HREmpWorkingDeptsController _empWorkingDeptCtrl;
        #endregion
        public HRDepartmentModule()
        {
            Name = "HRDepartment";
            CurrentModuleEntity = new HRDepartmentEntities();
            CurrentModuleEntity.Module = this;
            InitializeModule();
        }

        public override void InitializeModule()
        {
            base.InitializeModule();
            this._employeeCtrl = new HREmployeesController();
            this._empWorkingDeptCtrl = new HREmpWorkingDeptsController();
        }
        /// <summary>
        /// Remove an item from the room list of the current department
        /// </summary>
        public void RemoveItemFromList()
        {
            HRDepartmentEntities entity = (HRDepartmentEntities)CurrentModuleEntity;
            entity.DepartmentRoomList.RemoveSelectedRowObjectFromList();
        }

        public void RemoveSelectedItemFromRoomBedList()
        {
            HRDepartmentEntities entity = (HRDepartmentEntities)CurrentModuleEntity;
            BOSGridControl roomBedsGridControl = (BOSGridControl)Controls[HRDepartmentModule.RoomBedGridControlName];
            BOSList<HRRoomBedsInfo> roomBedList = (BOSList<HRRoomBedsInfo>)((BindingSource)roomBedsGridControl.DataSource).DataSource;
            roomBedList.RemoveSelectedRowObjectFromList();
        }

        public override int ActionSave()
        {
            HRDepartmentsInfo department = (HRDepartmentsInfo)CurrentModuleEntity.MainObject;
            if (department.HRDepartmentStatusCombo == DepartmentStatus.InActive.ToString())
            {
                if (MessageBox.Show($"Bạn muốn phòng ban {department.HRDepartmentName} không hoạt động?",
                    "Thông báo", MessageBoxButtons.OKCancel, MessageBoxIcon.Question) == DialogResult.Cancel)
                    return 0;
                var defaultEmployees = _employeeCtrl.GetListBusinessObjects<HREmployeesInfo>(_employeeCtrl.GetAllDataByForeignColumn("FK_HRDepartmentID", department.HRDepartmentID));
                if (defaultEmployees != null && defaultEmployees.Count > 0)
                {
                    var employeesInfo = string.Empty;
                    var i = 1;
                    foreach (var item in defaultEmployees)
                    {
                        employeesInfo += $"{i}. {item.HREmployeeName} - {item.HREmployeeNo}{Environment.NewLine}";
                        i++;
                    }
                    MessageBox.Show($"Danh sách nhân viên thuộc khoa phòng {department.HRDepartmentName}:" +
                         $"{Environment.NewLine}{employeesInfo}{Environment.NewLine}Vui lòng chuyển/xóa khoa phòng ra khỏi nhân viên để tiếp tục.",
                         "KHÔNG THỂ THỰC HIỆN ĐƯỢC THAO TÁC NÀY", MessageBoxButtons.OK, MessageBoxIcon.Stop);
                    return 0;
                }
                var empWorkingDepts = _empWorkingDeptCtrl.GetListBusinessObjects<HREmpWorkingDeptsInfo>(_empWorkingDeptCtrl.GetAllDataByForeignColumn("FK_HRDepartmentID", department.HRDepartmentID));
                if (empWorkingDepts != null && empWorkingDepts.Count > 0)
                {
                    var employeesInfo = string.Empty;
                    var i = 1;
                    foreach (var item in empWorkingDepts)
                    {
                        var objEmployee = _employeeCtrl.GetObjectByID(item.FK_HREmployeeID) as HREmployeesInfo;
                        employeesInfo += $"{i}. {objEmployee.HREmployeeName} - {objEmployee.HREmployeeNo}{Environment.NewLine}";
                        i++;
                    }
                    MessageBox.Show($"Danh sách nhân viên thuộc khoa phòng {department.HRDepartmentName}:" +
                        $"{Environment.NewLine}{employeesInfo}{Environment.NewLine}Vui lòng chuyển/xóa khoa phòng ra khỏi nhân viên để tiếp tục.",
                        "KHÔNG THỂ THỰC HIỆN ĐƯỢC THAO TÁC NÀY", MessageBoxButtons.OK, MessageBoxIcon.Stop);
                    return 0;
                }
            }
            
            return base.ActionSave();
        }
    }
    #endregion
}
